presetParts.presetInit:
index = 0;
loop (300000,
  megabuf(index) = .1;
  gmegabuf(index) = 0;
  index = index + 1;
);

vol_=1;

q10 = rand(100) >= 30;
q11 = rand(100) >= 30;
q12 = (rand(100) >= 30)*9+3;
q13 = min(max((rand(100)/50-.5),.2),1);
q14 = 0;

presetParts.perFrame:
dec_m = exp(-3/fps);
dec_s = exp(-.6/fps);
dec_xs = exp(-.4/fps);
flen = 128; shapes = 16;

beat = (bass + treb + mid)/3;
beat_ = beat_*dec_m + (1-dec_m)*beat; 
is_beat = above(beat, peak*8) * above (time, t0+.2);
t0 = is_beat*time + (1-is_beat)*t0;
peak = is_beat * beat + (1-is_beat)*peak*dec_m;
index = (index + is_beat) %8;
q22 = peak;
q27 = index;

n = 0; vol = .5; bbase = 5000;
loop (flen,
  value = gmegabuf(n) * (1+1/(n+.5));
  trig = value >= megabuf(n);
  dec = if(trig,0.2,pow(.98-.1*n/flen,30/fps));
  megabuf(n) = megabuf(n)*dec + (1-dec)*value;
  vol = vol + pow(megabuf(n),2);
  n = n+1;
);
vol = sqrt(vol);
vol_ = dec_m*vol_ + (1-dec_m)*vol;

// post smoothing
n = 0;
loop (flen,
  value = megabuf(n);
  dec = if (megabuf(1000+n)<=value,.9,.95-0.1*n/flen);
  dec = pow(dec,30/fps);
//  dec = 1; //#
    megabuf(n+1000) = megabuf(n+1000)*dec+ (1-dec)*value/vol_;
  n = n+1;
);


// Berechnung Ortskoordinaten aus Spektrum
dist = 2; reduce = flen/shapes;
n = 2000; m = 1000+dist; k=0;
loop (shapes,
  betr = (megabuf(m)+megabuf(m-dist)+megabuf(m+dist))/3;
  megabuf(n)   = megabuf(m) - megabuf(m+dist);
  megabuf(n+1) = megabuf(m) - megabuf(m-dist);
  z1 = max(.03/betr,.05);
  z2 = ((k+q22*q14+time*2)%shapes)/shapes+.06;
  megabuf(n+2) = q13*z1+(1-q13)*z2;
  m = m + reduce; n = n+8; k= k+1;
);


//Projektion
n = 1000; m = 2000;
loop (shapes,
  gmegabuf(n) = megabuf(m)/megabuf(m+2);
  gmegabuf(n+1) = megabuf(m+1)/megabuf(m+2);
  gmegabuf(n+2) = megabuf(m+2);
  mx = mx + gmegabuf(n)/shapes/fps;
  my = my + gmegabuf(n+1)/shapes/fps;
  n = n+8; m = m+8;
);


q1 = sin(8*mx+time*.1)/2;
q2 = sin(-8*my+time*.03);
q3 = atan2(gmegabuf(1000+8),gmegabuf(1000+8+1));

trel = trel + bass_att/fps;
q4 = trel;

monitor = q13;

q32 = aspecty;
q31 = min(.996,dec_xs);

