ret += (GetBlur2(uv) + GetBlur2(uv1)) *min(.5+treb_att/4,2) *(1+1*sw1) * saturate(1-lum(ret)/2);
ret += !sw1*back;
ret = lerp(ret*(hue_shader*2-1),ret,lum(ret));;
